import sys

def find_root(p):
    for i in range(len(p)):
        if p[i] == i + 1:
            return i + 1
    return -1

def is_valid_sequence(p):
    visited = [False] * len(p)
    for i in range(len(p)):
        if visited[i]:
            continue
        current = i
        while not visited[current]:
            visited[current] = True
            current = p[current] - 1
        if current != i:
            return False
    return True

def make_valid_sequence(n, a):
    if is_valid_sequence(a):
        return 0, a

    changes = 0
    for i in range(n):
        if a[i] != i + 1:
            changes += 1
            a[i] = find_root(a)
            if is_valid_sequence(a):
                return changes, a
    return changes, a

# Read input
n = int(sys.stdin.readline().strip())
a = list(map(int, sys.stdin.readline().strip().split()))

# Make the sequence valid
changes, valid_sequence = make_valid_sequence(n, a)

# Output the result
print(changes)
print(' '.join(map(str, valid_sequence)))
